From 7f94a76279302322b94010fcd1639d9f7412ca5b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:39:39 +0100
Subject: [PATCH] applets/notifications: Keep the file menu on screen when the
 notification moves

The file menu followed its notification without being placed again, so
it ran off the screen when the notification slid down. Now it's moved
once the notification's new position is applied, so it's placed again.

BUG: 486595
---
 applets/notifications/filemenu.cpp | 53 ++++++++++++++++++++++++++++++
 1 file changed, 53 insertions(+)

diff --git a/applets/notifications/filemenu.cpp b/applets/notifications/filemenu.cpp
index 19396e79fb..1a6b67ec79 100644
--- a/applets/notifications/filemenu.cpp
+++ b/applets/notifications/filemenu.cpp
@@ -11,9 +11,12 @@
 #include <QIcon>
 #include <QMenu>
 #include <QMimeData>
+#include <QPointer>
 #include <QQuickWindow>
 #include <QTimer>

+#include <memory>
+
 #include <KConfigGroup>
 #include <KFileItemActions>
 #include <KFileItemListProperties>
@@ -240,10 +243,60 @@ void FileMenu::open(int x, int y)
         window->setProperty("_q_waylandPopupConstraintAdjustment", 1u | 8u); // slide_x | flip_y
     } else {
         pos = m_visualParent->mapToGlobal(QPointF(x, y)).toPoint();
+
+        // Anchor to the click position in the notification, so the menu can be placed again when that moves.
+        window->setProperty("_q_waylandPopupAnchorRect", QRect{m_visualParent->mapToScene(QPointF(x, y)).toPoint(), QSize{1, 1}});
+        window->setProperty("_q_waylandPopupAnchor", int(Qt::TopEdge | Qt::LeftEdge));
+        window->setProperty("_q_waylandPopupGravity", int(Qt::BottomEdge | (qApp->isRightToLeft() ? Qt::LeftEdge : Qt::RightEdge)));
+        window->setProperty("_q_waylandPopupConstraintAdjustment", 1u | 2u | 8u); // slide_x | slide_y | flip_y
     }

     menu->popup(pos);

+    // The menu moves along with the notification but isn't placed again, so it can end up off-screen when the
+    // notification slides down. Moving it makes Qt send a new positioner, so the compositor places it again. That only
+    // works once the compositor has applied the frame carrying the notification's new position, which is certain when
+    // the next frame is swapped (Qt waits for the previous frame callback), so move it then.
+    QQuickWindow *parentWindow = m_visualParent->window();
+    struct ParentPosition {
+        QPoint synchronized;
+        QPoint swapped;
+        QPoint applied;
+    };
+    const QPoint startPos = parentWindow->position();
+    auto parentPos = std::make_shared<ParentPosition>(startPos, startPos, startPos);
+    connect(
+        parentWindow,
+        &QQuickWindow::afterSynchronizing,
+        menu,
+        [parentWindow, parentPos] {
+            parentPos->synchronized = parentWindow->position();
+        },
+        Qt::DirectConnection);
+    connect(
+        parentWindow,
+        &QQuickWindow::frameSwapped,
+        menu,
+        [parentWindow, parentPos, menu = QPointer(menu)] {
+            if (parentPos->swapped != parentPos->applied) {
+                const QPoint delta = parentPos->swapped - parentPos->applied;
+                parentPos->applied = parentPos->swapped;
+                QMetaObject::invokeMethod(
+                    parentWindow,
+                    [menu, delta] {
+                        if (menu && menu->isVisible()) {
+                            menu->move(menu->pos() + delta);
+                        }
+                    },
+                    Qt::QueuedConnection);
+            }
+            parentPos->swapped = parentPos->synchronized;
+            if (parentPos->swapped != parentPos->applied) {
+                QMetaObject::invokeMethod(parentWindow, &QQuickWindow::update, Qt::QueuedConnection);
+            }
+        },
+        Qt::DirectConnection);
+
     m_visible = true;
     Q_EMIT visibleChanged();
 }
